function imageData(label: string, color: string) {
  if (typeof document === "undefined") return "";

  const canvas = document.createElement("canvas");
  canvas.width = 720;
  canvas.height = 900;
  const context = canvas.getContext("2d");
  if (!context) return "";

  const gradient = context.createLinearGradient(0, 0, 720, 900);
  gradient.addColorStop(0, color);
  gradient.addColorStop(1, "#66709c");
  context.fillStyle = gradient;
  context.fillRect(0, 0, 720, 900);

  context.fillStyle = "rgba(255,255,255,.16)";
  context.beginPath();
  context.arc(575, 180, 120, 0, Math.PI * 2);
  context.fill();

  context.fillStyle = "rgba(255,255,255,.18)";
  context.beginPath();
  context.moveTo(0, 690);
  context.lineTo(210, 430);
  context.lineTo(370, 610);
  context.lineTo(490, 465);
  context.lineTo(720, 770);
  context.lineTo(720, 900);
  context.lineTo(0, 900);
  context.closePath();
  context.fill();

  context.fillStyle = "#ffffff";
  context.font = "52px Georgia, serif";
  context.fillText(label, 64, 760, 590);
  context.fillStyle = "rgba(255,255,255,.72)";
  context.font = "20px monospace";
  context.fillText("LEAFIA LAB", 66, 812);

  return canvas.toDataURL("image/png");
}

